const data = $input.first().json;
const hourly = data.hourly;

// Combine parallel arrays into readable hourly objects
const forecast = hourly.time.map((time, i) => {
  const hour = time.split('T')[1]; // Extract "14:00" from "2026-08-06T14:00"
  return {
    hour: hour,
    temperature_c: hourly.temperature_2m[i],
    cloud_cover_pct: hourly.cloud_cover[i],
    wind_kmh: hourly.wind_speed_10m[i],
    rain_probability_pct: hourly.precipitation_probability[i]
  };
});

return [{ json: { forecast, location: 'Kraków', date: hourly.time[0].split('T')[0] } }];

const claudeResponse = $input.first().json;

// Find text block (skip thinking blocks)
const textBlock = claudeResponse.content?.find(block => block.type === 'text');

// Graceful fallback if no text
if (!textBlock) {
  return [{ 
    json: {
      best_window: "N/A",
      score: 0,
      temperature: "unknown",
      conditions: "Weather advisor could not complete analysis",
      reasoning: "The LLM returned only thinking output without a final decision — likely due to token budget. Please check max_tokens setting.",
      location_suggestion: "Skip today or check forecast manually",
      verdict: "SKIP_TODAY"
    }
  }];
}

// Clean the text — remove markdown code fences if present
let cleanText = textBlock.text.trim();

// Strip ```json ... ``` or ``` ... ``` wrappers
if (cleanText.startsWith('```')) {
  cleanText = cleanText
    .replace(/^```(?:json)?\s*/, '')  // Remove opening ```json or ```
    .replace(/\s*```$/, '')            // Remove closing ```
    .trim();
}

// Parse the cleaned JSON
try {
  const parsed = JSON.parse(cleanText);
  return [{ json: parsed }];
} catch (e) {
  return [{ 
    json: {
      best_window: "N/A",
      score: 0,
      temperature: "unknown",
      conditions: "Could not parse Claude response",
      reasoning: `Parse error: ${e.message}. Raw text: ${cleanText.substring(0, 200)}`,
      location_suggestion: "Skip today",
      verdict: "SKIP_TODAY"
    }
  }];
}
